using System.Security.Claims;
using Microsoft.AspNetCore.Identity;
using Microsoft.EntityFrameworkCore;
using ScholarshipExam.Core;
using ScholarshipExam.Infrastructure;
namespace ScholarshipExam.Api;
public static class AdminEndpoints {
 public static void MapAdmin(this WebApplication app){
  var admin=app.MapGroup("/api/admin").RequireAuthorization(p=>p.RequireRole("Administrator"));
  admin.MapGet("/dashboard",async(AppDb db)=>new{users=await db.Users.CountAsync(),exams=await db.Exams.CountAsync(),published=await db.Exams.CountAsync(x=>x.Status=="Published"),pendingPayments=await db.Payments.CountAsync(x=>x.Status=="Pending"),attempts=await db.Attempts.CountAsync(),completed=await db.Attempts.CountAsync(x=>x.Status!="Active"),subscriptions=await db.Subscriptions.CountAsync()});
  admin.MapGet("/exams",async(AppDb db)=>await db.Exams.OrderBy(x=>x.ExternalKey).Select(e=>new{e.Id,e.ExternalKey,e.Title,e.Description,e.DurationMinutes,e.PassPercentage,e.Status,e.TeacherReviewed,questionCount=e.Questions.Count}).ToListAsync());
  admin.MapGet("/exams/{id:guid}",async(Guid id,AppDb db)=>{var e=await db.Exams.AsNoTracking().Include(x=>x.Questions).ThenInclude(x=>x.Options).SingleOrDefaultAsync(x=>x.Id==id);return e==null?Results.NotFound():Results.Ok(e);});
  admin.MapPost("/exams",async(ExamDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>{Input.Validate(dto);Input.Check(dto.DurationMinutes is >=5 and <=120&&dto.PassPercentage is >=0 and <=100,"Invalid duration or pass threshold.");return await gate.Run("catalog",async()=>{var e=new Exam{ExternalKey="custom-"+Guid.NewGuid().ToString("N"),Title=dto.Title,Description=dto.Description,DurationMinutes=dto.DurationMinutes,PassPercentage=dto.PassPercentage};db.Exams.Add(e);c.Audit(actor.UserId(),"exam.create",e.Id.ToString());await Task.CompletedTask;return Results.Ok(new{e.Id});});});
  admin.MapPut("/exams/{id:guid}",async(Guid id,ExamDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>{Input.Validate(dto);Input.Check(dto.DurationMinutes is >=5 and <=120&&dto.PassPercentage is >=0 and <=100,"Invalid duration or pass threshold.");return await gate.Run("catalog",async()=>{await c.Editable(id);var e=await db.Exams.FindAsync(id);Input.Check(e!=null,"Not found.",404);e!.Title=dto.Title;e.Description=dto.Description;e.DurationMinutes=dto.DurationMinutes;e.PassPercentage=dto.PassPercentage;e.TeacherReviewed=false;e.Status="Draft";e.ImportHash="";e.UpdatedAt=DateTime.UtcNow;c.Audit(actor.UserId(),"exam.edit",id.ToString());return Results.Ok(new{e.Id});});});
  admin.MapPost("/exams/{id:guid}/publish",async(Guid id,PublishDto dto,ContentService c,ClaimsPrincipal actor)=>await c.Publish(id,dto.ConfirmTeacherReview,actor.UserId()));
  admin.MapPost("/exams/{id:guid}/{action}",async(Guid id,string action,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>{Input.Check(action is "unpublish" or "archive","Unknown action.",404);return await gate.Run("catalog",async()=>{var e=await db.Exams.FindAsync(id);Input.Check(e!=null,"Not found.",404);if(action=="archive")await c.Editable(id);e!.Status=action=="archive"?"Archived":"Draft";c.Audit(actor.UserId(),"exam."+action,id.ToString());return Results.Ok(new{e.Status});});});
  admin.MapPost("/exams/{id:guid}/questions",async(Guid id,QuestionDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>{ContentService.ValidateQuestion(dto);return await gate.Run("catalog",async()=>{await c.Editable(id);var e=await db.Exams.FindAsync(id);Input.Check(e!=null,"Not found.",404);Input.Check(!await db.Questions.AnyAsync(x=>x.ExamId==id&&x.DisplayOrder==dto.DisplayOrder),"Display order already used.",409);var q=ContentService.Map(id,dto);db.Questions.Add(q);e!.TeacherReviewed=false;e.Status="Draft";e.ImportHash="";c.Audit(actor.UserId(),"question.create",q.Id.ToString());return Results.Ok(new{q.Id});});});
  admin.MapPut("/questions/{id:guid}",async(Guid id,QuestionDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>{ContentService.ValidateQuestion(dto);return await gate.Run("catalog",async()=>{var q=await db.Questions.Include(x=>x.Options).SingleOrDefaultAsync(x=>x.Id==id);Input.Check(q!=null,"Not found.",404);await c.Editable(q!.ExamId);Input.Check(!await db.Questions.AnyAsync(x=>x.ExamId==q.ExamId&&x.DisplayOrder==dto.DisplayOrder&&x.Id!=id),"Display order already used.",409);db.Options.RemoveRange(q.Options);await db.SaveChangesAsync();q.QuestionText=dto.QuestionText;q.Explanation=dto.Explanation;q.Topic=dto.Topic;q.Marks=dto.Marks;q.DisplayOrder=dto.DisplayOrder;q.DiagramKey=dto.DiagramKey;q.DiagramAlt=dto.DiagramAlt;q.Options=dto.Options.Select(o=>new QuestionOption{QuestionId=q.Id,Key=o.Key,Text=o.Text,IsCorrect=o.Key==dto.CorrectOptionKey}).ToList();var e=await db.Exams.FindAsync(q.ExamId);e!.TeacherReviewed=false;e.Status="Draft";e.ImportHash="";c.Audit(actor.UserId(),"question.edit",id.ToString());return Results.Ok(new{q.Id});});});
  admin.MapDelete("/questions/{id:guid}",async(Guid id,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>await gate.Run("catalog",async()=>{var q=await db.Questions.FindAsync(id);Input.Check(q!=null,"Not found.",404);await c.Editable(q!.ExamId);db.Questions.Remove(q);var e=await db.Exams.FindAsync(q.ExamId);e!.TeacherReviewed=false;e.Status="Draft";e.ImportHash="";c.Audit(actor.UserId(),"question.delete",id.ToString());return Results.NoContent();}));
  admin.MapPost("/import",async(ImportDto dto,ContentService c,ClaimsPrincipal actor)=>await c.Import(dto,actor.UserId()));
  admin.MapGet("/payments",async(int? page,AppDb db)=>await db.Payments.OrderByDescending(x=>x.CreatedAt).Skip((Math.Max(page??1,1)-1)*50).Take(50).ToListAsync());
  admin.MapPost("/payments/{id:guid}/approve",async(Guid id,ReviewDto dto,PaymentService p,ClaimsPrincipal actor)=>await p.Review(id,dto,true,actor.UserId()));
  admin.MapPost("/payments/{id:guid}/reject",async(Guid id,ReviewDto dto,PaymentService p,ClaimsPrincipal actor)=>await p.Review(id,dto,false,actor.UserId()));
  admin.MapGet("/students",async(int? page,AppDb db)=>await db.Users.OrderBy(x=>x.Email).Skip((Math.Max(page??1,1)-1)*50).Take(50).Select(x=>new{x.Id,x.Email,x.DisplayName,x.Disabled,roles=db.UserRoles.Where(ur=>ur.UserId==x.Id).Join(db.Roles,ur=>ur.RoleId,role=>role.Id,(ur,role)=>role.Name).ToArray()}).ToListAsync());
  admin.MapPost("/students/{id}/toggle",async(string id,ClaimsPrincipal actor,AppDb db,WorkLock gate,ContentService c)=>await gate.Run("accounts",async()=>{Input.Check(id!=actor.UserId(),"Cannot disable your own account.");var u=await db.Users.FindAsync(id);Input.Check(u!=null,"Not found.",404);u!.Disabled=!u.Disabled;c.Audit(actor.UserId(),"user.toggle",id);return Results.Ok(new{u.Disabled});}));
  admin.MapGet("/subscriptions",async(int? page,AppDb db)=>await db.Subscriptions.OrderByDescending(x=>x.CreatedAt).Skip((Math.Max(page??1,1)-1)*50).Take(50).Select(x=>new{x.Id,x.StudentId,x.PaymentId,x.Status,x.CreatedAt,remaining=x.Entitlements.Count(e=>!e.Used)}).ToListAsync());
  admin.MapPost("/subscriptions/{id:guid}/{action}",async(Guid id,string action,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>await gate.Run("subscriptions",async()=>{Input.Check(action is "suspend" or "resume","Unknown action.",404);var sub=await db.Subscriptions.FindAsync(id);Input.Check(sub!=null,"Not found.",404);sub.Status=action=="suspend"?"Suspended":"Active";c.Audit(actor.UserId(),"subscription."+action,id.ToString());return Results.Ok(new{sub.Id,sub.Status});}));
  admin.MapGet("/attempts",async(int? page,AppDb db)=>await db.Attempts.OrderByDescending(x=>x.CreatedAt).Skip((Math.Max(page??1,1)-1)*50).Take(50).Select(x=>new{x.Id,x.StudentId,x.ExamId,x.Status,x.Score,x.Percentage,x.CreatedAt}).ToListAsync());
  admin.MapGet("/attempts/{id:guid}/result",async(Guid id,AppDb db,ExamService exams)=>{var owner=await db.Attempts.Where(x=>x.Id==id).Select(x=>x.StudentId).SingleOrDefaultAsync();Input.Check(owner!=null,"Not found.",404);return await exams.Result(id,owner!);});
  admin.MapGet("/rewards",async(AppDb db)=>await db.Rewards.OrderBy(x=>x.Code).ToListAsync());
  admin.MapPut("/rewards/{code}",async(string code,RewardDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>await gate.Run("rewards",async()=>{Input.Check(dto.Threshold is >=0 and <=100,"Threshold 0–100 required.");var reward=await db.Rewards.SingleOrDefaultAsync(x=>x.Code==code);Input.Check(reward!=null,"Not found.",404);reward!.Threshold=dto.Threshold;reward.Enabled=dto.Enabled;c.Audit(actor.UserId(),"reward.configure",code,$"Threshold={dto.Threshold}; enabled={dto.Enabled}");return Results.Ok(reward);}));
  admin.MapGet("/settings",async(AppDb db)=>await db.Settings.SingleAsync());
  admin.MapPut("/settings",async(SettingsDto dto,AppDb db,WorkLock gate,ContentService c,ClaimsPrincipal actor)=>await gate.Run("settings",async()=>{Input.Check(dto.PaymentInstructions!=null&&dto.PaymentInstructions.Length<=4000&&dto.ContactEmail!=null&&dto.ContactEmail.Length<=200,"Settings too long.");Input.Check(!dto.AcceptPayments||(!string.IsNullOrWhiteSpace(dto.PaymentInstructions)&&new System.ComponentModel.DataAnnotations.EmailAddressAttribute().IsValid(dto.ContactEmail)),"Payment instructions and valid support email are required.");var s=await db.Settings.SingleAsync();s.PaymentInstructions=dto.PaymentInstructions!;s.ContactEmail=dto.ContactEmail!;s.AcceptPayments=dto.AcceptPayments;c.Audit(actor.UserId(),"settings.update","1");return Results.Ok(s);}));
  admin.MapGet("/audit",async(int? page,AppDb db)=>await db.Audit.OrderByDescending(x=>x.CreatedAt).Skip((Math.Max(page??1,1)-1)*50).Take(50).ToListAsync());
 }
}

